#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
"""Read Playwright JSON reports and trace entries through bounded trust gates."""

from __future__ import annotations

import argparse
from collections.abc import Iterator
from contextlib import contextmanager
import hashlib
from io import BytesIO
import json
import math
import os
from pathlib import Path, PurePosixPath
import re
import stat
import sys
import tempfile
from urllib.parse import urlsplit, urlunsplit
import zipfile
import zlib

sys.path.insert(0, str(Path(__file__).resolve().parent))
from residual_credentials import (  # noqa: E402
    AUTH_SCHEME_NAMES,
    build_assignment_redactor,
    build_header_pattern,
    has_residual_credential,
    header_substitution,
    redact_credential_shapes,
    sanitize_diagnostic,
)


MAX_REPORT_BYTES = 8 * 1024 * 1024
MAX_ARCHIVE_BYTES = 64 * 1024 * 1024
MAX_IMAGE_BYTES = 64 * 1024 * 1024
MAX_VIDEO_BYTES = 512 * 1024 * 1024
MAX_JSON_DEPTH = 100
MAX_JSON_NODES = 200_000
MAX_OUTPUT_BYTES = 1024 * 1024
MAX_OUTPUT_RECORDS = 10_000
MAX_ATTEMPTS_PER_TEST = 100
MAX_STRING_CHARS = 4_000
MAX_ZIP_ENTRIES = 10_000
MAX_ZIP_ENTRY_BYTES = 64 * 1024 * 1024
MAX_SELECTED_ENTRY_BYTES = 32 * 1024 * 1024
MAX_ZIP_TOTAL_BYTES = 512 * 1024 * 1024
MAX_COMPRESSION_RATIO = 200
MAX_NDJSON_LINE_BYTES = 1024 * 1024
EXPECTED_TRACE_ENTRY = re.compile(r"(?:[0-9]+-)?trace\.(?:trace|network)\Z")
REDACTED = "[REDACTED]"
SENSITIVE_KEY_FRAGMENTS = (
    "apikey",
    "authorization",
    "body",
    "clientsecret",
    "cookie",
    "credential",
    "formdata",
    "passwd",
    "password",
    "payload",
    "postdata",
    "query",
    "secret",
    "token",
)
REDACT_TEXT_ASSIGNMENTS = build_assignment_redactor(
    "body|post[_-]?data|payload"
)
SENSITIVE_HEADER = build_header_pattern()
URL = re.compile(r"https?://[^\s\"'<>]+")
QUERY_ASSIGNMENT = re.compile(r"([?&][^=\s&#]+)=([^&#\s]*)")
# Scheme list owned by residual_credentials so this redactor and the gate
# that checks its output can never disagree about which schemes exist.
AUTH_SCHEME = re.compile(
    r"(?i)\b(?:" + AUTH_SCHEME_NAMES + r")\s+[A-Za-z0-9._~+/=-]+"
)
ALLOWED_ZIP_METHODS = {zipfile.ZIP_STORED, zipfile.ZIP_DEFLATED}
PLAYWRIGHT_OUTCOMES = {"expected", "unexpected", "flaky", "skipped"}
PLAYWRIGHT_RESULT_STATUSES = {
    "passed",
    "failed",
    "timedOut",
    "skipped",
    "interrupted",
}
PLAYWRIGHT_STAT_COUNTERS = ("expected", "skipped", "unexpected", "flaky")
SECURE_OPEN_PLATFORM_ERROR = (
    "secure artifact reading requires POSIX descriptor-relative no-follow "
    "filesystem APIs (macOS/Linux); on Windows run this reader inside WSL "
    "against artifacts stored under a trusted WSL filesystem root"
)


def require_secure_descriptor_support() -> None:
    if (
        not isinstance(getattr(os, "O_DIRECTORY", None), int)
        or not isinstance(getattr(os, "O_NOFOLLOW", None), int)
        or os.open not in getattr(os, "supports_dir_fd", set())
    ):
        raise ValueError(SECURE_OPEN_PLATFORM_ERROR)


def reject_duplicate_keys(pairs: list[tuple[str, object]]) -> dict[str, object]:
    value: dict[str, object] = {}
    for position, (key, item) in enumerate(pairs):
        if key in value:
            # The key itself is artifact-controlled and this error travels to
            # stderr through `parser.error`, which never reaches the emission
            # gate. Report the position instead of echoing the bytes.
            raise ValueError(f"duplicate JSON key at object entry {position}")
        value[key] = item
    return value


def reject_nonfinite_number(token: str) -> object:
    raise ValueError(f"non-finite JSON number is forbidden: {token}")


def parse_finite_float(token: str) -> float:
    value = float(token)
    if not math.isfinite(value):
        raise ValueError(f"non-finite JSON number is forbidden: {token}")
    return value


def strict_json_loads(data: bytes | str) -> object:
    if isinstance(data, bytes):
        if data.startswith(b"\xef\xbb\xbf"):
            raise ValueError("JSON BOM is forbidden")
        try:
            text = data.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise ValueError(f"invalid JSON UTF-8: {exc}") from exc
    else:
        text = data
    if text.startswith("\ufeff"):
        raise ValueError("JSON BOM is forbidden")
    start = len(text) - len(text.lstrip())
    if start == len(text):
        raise ValueError("invalid JSON: input is empty")
    decoder = json.JSONDecoder(
        object_pairs_hook=reject_duplicate_keys,
        parse_constant=reject_nonfinite_number,
        parse_float=parse_finite_float,
    )
    try:
        value, end = decoder.raw_decode(text, start)
    except (RecursionError, json.JSONDecodeError) as exc:
        raise ValueError(f"invalid JSON: {exc}") from exc
    if text[end:].strip():
        raise ValueError("invalid JSON: trailing data is forbidden")
    return value


def open_trusted_directory(path: Path, description: str) -> int:
    """Open an absolute directory from the filesystem root without following links."""
    require_secure_descriptor_support()
    absolute = Path(os.path.abspath(path))
    close_on_exec = getattr(os, "O_CLOEXEC", 0)
    directory_flags = os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | close_on_exec
    current_fd: int | None = None
    try:
        current_fd = os.open(absolute.anchor, directory_flags)
        for component in absolute.parts[1:]:
            next_fd = os.open(component, directory_flags, dir_fd=current_fd)
            os.close(current_fd)
            current_fd = next_fd
        return current_fd
    except OSError as exc:
        if current_fd is not None:
            os.close(current_fd)
        raise ValueError(
            f"{description} contains a symlink or is unavailable: {path}: {exc}"
        ) from exc


def descriptor_fingerprint(metadata: os.stat_result) -> tuple[int, ...]:
    fingerprint = (
        metadata.st_dev,
        metadata.st_ino,
        metadata.st_mode,
        metadata.st_size,
        metadata.st_mtime_ns,
    )
    ctime_ns = getattr(metadata, "st_ctime_ns", None)
    if ctime_ns is not None:
        return fingerprint + (ctime_ns,)
    return fingerprint


def require_unchanged_descriptor(
    artifact_fd: int,
    original_metadata: os.stat_result,
    artifact: Path,
) -> os.stat_result:
    current_metadata = os.fstat(artifact_fd)
    if descriptor_fingerprint(current_metadata) != descriptor_fingerprint(
        original_metadata
    ):
        raise ValueError(f"artifact changed while being read: {artifact}")
    return current_metadata


@contextmanager
def open_artifact_descriptor(
    report_root: Path,
    artifact: Path,
    max_bytes: int,
) -> Iterator[tuple[int, os.stat_result]]:
    require_secure_descriptor_support()
    absolute_root = Path(os.path.abspath(report_root))
    absolute_artifact = Path(os.path.abspath(artifact))
    try:
        lexical_relative = absolute_artifact.relative_to(absolute_root)
    except ValueError as exc:
        raise ValueError(f"artifact is outside the report root: {artifact}") from exc
    if not lexical_relative.parts:
        raise ValueError(f"artifact is not a regular file: {artifact}")

    close_on_exec = getattr(os, "O_CLOEXEC", 0)
    directory_flags = os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | close_on_exec
    file_flags = (
        os.O_RDONLY
        | os.O_NOFOLLOW
        | getattr(os, "O_NONBLOCK", 0)
        | close_on_exec
    )
    root_fd = open_trusted_directory(absolute_root, "report root")
    current_fd = root_fd
    opened_directory_fds: list[int] = []
    artifact_fd: int | None = None
    try:
        for component in lexical_relative.parts[:-1]:
            next_fd = os.open(component, directory_flags, dir_fd=current_fd)
            opened_directory_fds.append(next_fd)
            current_fd = next_fd
        artifact_fd = os.open(
            lexical_relative.parts[-1],
            file_flags,
            dir_fd=current_fd,
        )
        metadata = os.fstat(artifact_fd)
        if not stat.S_ISREG(metadata.st_mode):
            raise ValueError(f"artifact is not a regular file: {artifact}")
        if metadata.st_size > max_bytes:
            raise ValueError(
                f"artifact exceeds the {max_bytes}-byte limit: {artifact}"
            )
        yield artifact_fd, metadata
    except OSError as exc:
        raise ValueError(
            f"unsafe, symlinked, or unreadable artifact path: {artifact}: {exc}"
        ) from exc
    finally:
        if artifact_fd is not None:
            os.close(artifact_fd)
        for directory_fd in reversed(opened_directory_fds):
            os.close(directory_fd)
        os.close(root_fd)


def read_bounded_file(
    report_root: Path,
    artifact: Path,
    max_bytes: int,
) -> bytes:
    with open_artifact_descriptor(
        report_root,
        artifact,
        max_bytes,
    ) as (artifact_fd, metadata):

        chunks: list[bytes] = []
        remaining = max_bytes + 1
        while remaining:
            chunk = os.read(artifact_fd, min(64 * 1024, remaining))
            if not chunk:
                break
            chunks.append(chunk)
            remaining -= len(chunk)
        data = b"".join(chunks)
        if len(data) > max_bytes:
            raise ValueError(
                f"artifact exceeds the {max_bytes}-byte limit: {artifact}"
            )
        current_metadata = require_unchanged_descriptor(
            artifact_fd,
            metadata,
            artifact,
        )
        if len(data) != current_metadata.st_size:
            raise ValueError(f"artifact changed while being read: {artifact}")
        return data


def write_all(file_descriptor: int, data: bytes) -> None:
    view = memoryview(data)
    while view:
        written = os.write(file_descriptor, view)
        if written <= 0:
            raise OSError("snapshot write made no progress")
        view = view[written:]


def remove_failed_snapshot(
    snapshot_path: Path | None,
    snapshot_directory: Path | None,
) -> None:
    if snapshot_path is not None:
        try:
            snapshot_path.unlink()
        except FileNotFoundError:
            pass
    if snapshot_directory is not None:
        try:
            snapshot_directory.rmdir()
        except FileNotFoundError:
            pass


def media_kind_and_limit(artifact: Path) -> tuple[str, int]:
    suffix = artifact.suffix.lower()
    if suffix == ".png":
        return "png", MAX_IMAGE_BYTES
    if suffix in {".jpg", ".jpeg"}:
        return "jpeg", MAX_IMAGE_BYTES
    if suffix == ".webm":
        return "webm", MAX_VIDEO_BYTES
    raise ValueError(
        "media mode accepts only Playwright .png, .jpg/.jpeg, and .webm files"
    )


def validate_media_header(kind: str, header: bytes) -> None:
    if kind == "png" and not header.startswith(b"\x89PNG\r\n\x1a\n"):
        raise ValueError("PNG artifact has an invalid signature")
    if kind == "jpeg" and not header.startswith(b"\xff\xd8\xff"):
        raise ValueError("JPEG artifact has an invalid signature")
    if kind == "webm" and (
        not header.startswith(b"\x1aE\xdf\xa3") or b"webm" not in header
    ):
        raise ValueError("WebM artifact has an invalid EBML/WebM signature")


def snapshot_metadata(
    report_root: Path,
    artifact: Path,
    *,
    kind: str,
    max_bytes: int,
    validate_header: bool,
) -> dict[str, object]:
    snapshot_directory: Path | None = None
    snapshot_path: Path | None = None
    try:
        with open_artifact_descriptor(
            report_root,
            artifact,
            max_bytes,
        ) as (artifact_fd, metadata):
            header = os.read(artifact_fd, 4096)
            if validate_header:
                validate_media_header(kind, header)
            os.lseek(artifact_fd, 0, os.SEEK_SET)

            snapshot_directory = Path(
                tempfile.mkdtemp(prefix="e2e-playwright-artifact-")
            )
            os.chmod(snapshot_directory, stat.S_IRWXU)
            snapshot_path = snapshot_directory / f"artifact.{kind}"
            snapshot_fd = os.open(
                snapshot_path,
                os.O_WRONLY
                | os.O_CREAT
                | os.O_EXCL
                | getattr(os, "O_CLOEXEC", 0)
                | getattr(os, "O_NOFOLLOW", 0),
                stat.S_IRUSR,
            )
            digest = hashlib.sha256()
            copied = 0
            try:
                while True:
                    chunk = os.read(artifact_fd, 64 * 1024)
                    if not chunk:
                        break
                    copied += len(chunk)
                    if copied > max_bytes:
                        raise ValueError(
                            f"artifact exceeds the {max_bytes}-byte limit: "
                            f"{artifact}"
                        )
                    digest.update(chunk)
                    write_all(snapshot_fd, chunk)
                current_metadata = require_unchanged_descriptor(
                    artifact_fd,
                    metadata,
                    artifact,
                )
                if copied != current_metadata.st_size:
                    raise ValueError(f"artifact changed while being read: {artifact}")
                os.fsync(snapshot_fd)
                os.fchmod(snapshot_fd, stat.S_IRUSR)
                snapshot_stat = os.fstat(snapshot_fd)
                if (
                    not stat.S_ISREG(snapshot_stat.st_mode)
                    or snapshot_stat.st_size != copied
                    or stat.S_IMODE(snapshot_stat.st_mode) != stat.S_IRUSR
                ):
                    raise ValueError("artifact snapshot validation failed")
            finally:
                os.close(snapshot_fd)

        return {
            "path": str(snapshot_path),
            "snapshot_directory": str(snapshot_directory),
            "kind": kind,
            "size": copied,
            "sha256": digest.hexdigest(),
            "lifecycle": (
                "temporary owner-only read-only snapshot; delete "
                "snapshot_directory after the viewer closes"
            ),
        }
    except BaseException:
        remove_failed_snapshot(snapshot_path, snapshot_directory)
        raise


def media_metadata(report_root: Path, artifact: Path) -> dict[str, object]:
    kind, max_bytes = media_kind_and_limit(artifact)
    return snapshot_metadata(
        report_root,
        artifact,
        kind=kind,
        max_bytes=max_bytes,
        validate_header=True,
    )


def snapshot_validated_bytes(
    data: bytes,
    *,
    kind: str,
) -> dict[str, object]:
    snapshot_directory: Path | None = None
    snapshot_path: Path | None = None
    try:
        snapshot_directory = Path(
            tempfile.mkdtemp(prefix="e2e-playwright-artifact-")
        )
        os.chmod(snapshot_directory, stat.S_IRWXU)
        snapshot_path = snapshot_directory / f"artifact.{kind}"
        snapshot_fd = os.open(
            snapshot_path,
            os.O_WRONLY
            | os.O_CREAT
            | os.O_EXCL
            | getattr(os, "O_CLOEXEC", 0)
            | getattr(os, "O_NOFOLLOW", 0),
            stat.S_IRUSR,
        )
        try:
            write_all(snapshot_fd, data)
            os.fsync(snapshot_fd)
            os.fchmod(snapshot_fd, stat.S_IRUSR)
            snapshot_stat = os.fstat(snapshot_fd)
            if (
                not stat.S_ISREG(snapshot_stat.st_mode)
                or snapshot_stat.st_size != len(data)
                or stat.S_IMODE(snapshot_stat.st_mode) != stat.S_IRUSR
            ):
                raise ValueError("artifact snapshot validation failed")
        finally:
            os.close(snapshot_fd)
        return {
            "path": str(snapshot_path),
            "snapshot_directory": str(snapshot_directory),
            "kind": kind,
            "size": len(data),
            "sha256": hashlib.sha256(data).hexdigest(),
            "lifecycle": (
                "temporary owner-only read-only snapshot; delete "
                "snapshot_directory after the viewer closes"
            ),
        }
    except BaseException:
        remove_failed_snapshot(snapshot_path, snapshot_directory)
        raise


def validate_json_shape(value: object) -> None:
    stack = [(value, 1)]
    nodes = 0
    while stack:
        current, depth = stack.pop()
        nodes += 1
        if nodes > MAX_JSON_NODES:
            raise ValueError(f"JSON exceeds the {MAX_JSON_NODES}-node limit")
        if depth > MAX_JSON_DEPTH:
            raise ValueError(f"JSON exceeds the {MAX_JSON_DEPTH}-level depth limit")
        if isinstance(current, dict):
            stack.extend((item, depth + 1) for item in current.values())
        elif isinstance(current, list):
            stack.extend((item, depth + 1) for item in current)


def bounded_string(value: object) -> str | None:
    if value is None:
        return None
    return redact_string(str(value))[:MAX_STRING_CHARS]


def bounded_scalar(value: object) -> object:
    if value is None or isinstance(value, (bool, int, float)):
        return value
    if isinstance(value, str):
        return bounded_string(value)
    return None


def bounded_location(value: object) -> dict[str, object] | None:
    if not isinstance(value, dict):
        return None
    return {
        "file": bounded_string(value.get("file")),
        "line": bounded_scalar(value.get("line")),
        "column": bounded_scalar(value.get("column")),
    }


def is_sensitive_key(key: object) -> bool:
    if not isinstance(key, str):
        return False
    normalized = re.sub(r"[^a-z0-9]", "", key.lower())
    return any(fragment in normalized for fragment in SENSITIVE_KEY_FRAGMENTS)


def redact_url(match: re.Match[str]) -> str:
    raw_url = match.group(0)
    trailing = ""
    while raw_url and raw_url[-1] in ".,;:)]}":
        trailing = raw_url[-1] + trailing
        raw_url = raw_url[:-1]
    try:
        parts = urlsplit(raw_url)
        hostname = parts.hostname or ""
        if ":" in hostname and not hostname.startswith("["):
            hostname = f"[{hostname}]"
        if parts.port is not None:
            hostname = f"{hostname}:{parts.port}"
        query = QUERY_ASSIGNMENT.sub(
            rf"\1={REDACTED}",
            f"?{parts.query}",
        )[1:]
        sanitized = urlunsplit(
            (parts.scheme, hostname, parts.path, query, parts.fragment)
        )
    except ValueError:
        sanitized = QUERY_ASSIGNMENT.sub(
            rf"\1={REDACTED}",
            raw_url,
        )
        sanitized = re.sub(r"(?<=://)[^/@\s]+@", "", sanitized)
    return sanitized + trailing


def redact_string(value: str) -> str:
    redacted = URL.sub(redact_url, value)
    redacted = AUTH_SCHEME.sub(REDACTED, redacted)
    redacted = redact_credential_shapes(redacted)
    redacted = SENSITIVE_HEADER.sub(header_substitution, redacted)
    redacted = REDACT_TEXT_ASSIGNMENTS(redacted)
    return QUERY_ASSIGNMENT.sub(rf"\1={REDACTED}", redacted)


def redact_sensitive(value: object, parent_key: object = None) -> object:
    if is_sensitive_key(parent_key):
        return REDACTED
    if isinstance(value, dict):
        header_name = value.get("name")
        sensitive_named_value = is_sensitive_key(header_name)
        return {
            key: (
                REDACTED
                if sensitive_named_value and key == "value"
                else redact_sensitive(item, key)
            )
            for key, item in value.items()
        }
    if isinstance(value, list):
        return [redact_sensitive(item) for item in value]
    if isinstance(value, str):
        return redact_string(value)
    return value



def error_message(value: object) -> str | None:
    if not isinstance(value, dict):
        return None
    return bounded_string(value.get("message"))


def synthetic_error_records(report: object) -> list[dict[str, object]]:
    assert isinstance(report, dict)
    sources: list[tuple[str | None, object]] = [
        (None, report.get("errors", []))
    ]
    for container_name in ("projects",):
        projects = report.get(container_name, [])
        if not isinstance(projects, list):
            raise ValueError(
                f"report JSON schema requires {container_name} to be an array"
            )
        for project in projects:
            if not isinstance(project, dict):
                raise ValueError("report JSON schema requires project objects")
            sources.append(
                (bounded_string(project.get("name")), project.get("errors", []))
            )
    config = report.get("config")
    if config is not None:
        if not isinstance(config, dict):
            raise ValueError("report JSON schema requires config to be an object")
        config_projects = config.get("projects", [])
        if not isinstance(config_projects, list):
            raise ValueError(
                "report JSON schema requires config.projects to be an array"
            )
        for project in config_projects:
            if not isinstance(project, dict):
                raise ValueError(
                    "report JSON schema requires config project objects"
                )
            sources.append(
                (bounded_string(project.get("name")), project.get("errors", []))
            )

    records: list[dict[str, object]] = []
    for project_name, errors in sources:
        if not isinstance(errors, list):
            raise ValueError("report JSON schema requires errors arrays")
        for error in errors:
            if not isinstance(error, dict):
                raise ValueError("report JSON schema requires error objects")
            message = error.get("message")
            stack = error.get("stack")
            if not isinstance(message, str) and not isinstance(stack, str):
                raise ValueError(
                    "report JSON schema requires error message or stack"
                )
            location = bounded_location(error.get("location"))
            records.append(
                {
                    "title": (
                        "[project error]"
                        if project_name is not None
                        else "[global error]"
                    ),
                    "file": location["file"] if location else None,
                    "line": location["line"] if location else None,
                    "projectName": project_name,
                    "outcome": "unexpected",
                    "retries": 0,
                    "attempts": [
                        {
                            "attempt": 0,
                            "status": "failed",
                            "duration": None,
                            "error": bounded_string(
                                message if isinstance(message, str) else stack
                            ),
                            "errorLocation": location,
                        }
                    ],
                }
            )
            if len(records) > MAX_OUTPUT_RECORDS:
                raise ValueError(
                    f"report exceeds the {MAX_OUTPUT_RECORDS}-error limit"
                )
    return records


def computed_test_outcome(test: dict[str, object]) -> str:
    expected_status = test.get("expectedStatus", "passed")
    if (
        not isinstance(expected_status, str)
        or expected_status not in PLAYWRIGHT_RESULT_STATUSES
    ):
        raise ValueError(
            "report JSON schema requires a valid test expectedStatus"
        )
    results = test.get("results")
    assert isinstance(results, list)
    skipped = 0
    expected = 0
    unexpected = 0
    for result in results:
        assert isinstance(result, dict)
        status = result.get("status")
        if (
            not isinstance(status, str)
            or status not in PLAYWRIGHT_RESULT_STATUSES
        ):
            raise ValueError(
                "report result status contradicts the Playwright JSON schema"
            )
        if status == "interrupted":
            unexpected += 1
            continue
        if status == "skipped" and expected_status == "skipped":
            skipped += 1
        elif status == "skipped":
            continue
        elif status == expected_status:
            expected += 1
        else:
            unexpected += 1
    if expected == 0 and unexpected == 0:
        return "skipped"
    if unexpected == 0:
        return "expected"
    if expected == 0 and skipped == 0:
        return "unexpected"
    return "flaky"


def report_specs(report: object) -> list[dict[str, object]]:
    if not isinstance(report, dict) or not isinstance(report.get("suites"), list):
        raise ValueError("report JSON schema requires a root suites array")

    specs: list[dict[str, object]] = []
    canonical_spec_ids: set[int] = set()
    suites = report["suites"]
    suite_stack = list(reversed(suites))
    while suite_stack:
        suite = suite_stack.pop()
        if not isinstance(suite, dict):
            raise ValueError("report JSON schema requires suite objects")
        child_suites = suite.get("suites", [])
        suite_specs = suite.get("specs")
        if not isinstance(child_suites, list) or not isinstance(suite_specs, list):
            raise ValueError(
                "report JSON schema requires suites/specs arrays on every suite"
            )
        suite_stack.extend(reversed(child_suites))
        for spec in suite_specs:
            if (
                not isinstance(spec, dict)
                or not isinstance(spec.get("ok"), bool)
                or not isinstance(spec.get("tests"), list)
            ):
                raise ValueError(
                    "report JSON schema requires each spec to have bool ok "
                    "and tests array"
                )
            canonical_spec_ids.add(id(spec))
            specs.append(spec)
            if len(specs) > MAX_OUTPUT_RECORDS:
                raise ValueError(
                    f"report exceeds the {MAX_OUTPUT_RECORDS}-spec limit"
                )
            for test in spec["tests"]:
                if (
                    not isinstance(test, dict)
                    or not isinstance(test.get("status"), str)
                    or not isinstance(test.get("results"), list)
                ):
                    raise ValueError(
                        "report JSON schema requires test status and results array"
                    )
                outcome = test["status"]
                if outcome not in PLAYWRIGHT_OUTCOMES:
                    raise ValueError(
                        "report JSON schema requires a valid test status"
                    )
                if len(test["results"]) > MAX_ATTEMPTS_PER_TEST:
                    raise ValueError(
                        f"test exceeds the "
                        f"{MAX_ATTEMPTS_PER_TEST}-attempt limit"
                    )
                for result in test["results"]:
                    if not isinstance(result, dict):
                        raise ValueError(
                            "report JSON schema requires result objects"
                        )
                computed_outcome = computed_test_outcome(test)
                if outcome != computed_outcome:
                    raise ValueError(
                        f"report test status={outcome} contradicts results "
                        f"outcome={computed_outcome}"
                    )
            expected_ok = all(
                test["status"] in {"expected", "flaky", "skipped"}
                for test in spec["tests"]
            )
            if spec["ok"] != expected_ok:
                raise ValueError(
                    f"report spec.ok={spec['ok']} contradicts test statuses"
                )

    # A spec-shaped object outside suites/specs is ambiguous. Reject it rather
    # than silently returning an empty/partial failure set.
    stack = [report]
    while stack:
        current = stack.pop()
        if isinstance(current, dict):
            if (
                "ok" in current
                and "tests" in current
                and id(current) not in canonical_spec_ids
            ):
                raise ValueError(
                    "report JSON schema contains a spec-shaped object outside "
                    "suites/specs"
                )
            stack.extend(current.values())
        elif isinstance(current, list):
            stack.extend(current)
    return specs


def validate_report_stats(
    report: object,
    specs: list[dict[str, object]],
) -> None:
    assert isinstance(report, dict)
    stats = report.get("stats")
    if not isinstance(stats, dict):
        raise ValueError("report JSON schema requires a root stats object")
    counters: dict[str, int] = {}
    for field in PLAYWRIGHT_STAT_COUNTERS:
        value = stats.get(field)
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            raise ValueError(
                f"report stats.{field} must be a nonnegative integer"
            )
        counters[field] = value
    duration = stats.get("duration")
    if duration is not None and (
        isinstance(duration, bool)
        or not isinstance(duration, (int, float))
        or duration < 0
    ):
        raise ValueError("report stats.duration must be a nonnegative number")
    start_time = stats.get("startTime")
    if start_time is not None and not isinstance(start_time, str):
        raise ValueError("report stats.startTime must be a string")

    parsed = {field: 0 for field in PLAYWRIGHT_STAT_COUNTERS}
    for spec in specs:
        tests = spec["tests"]
        assert isinstance(tests, list)
        for test in tests:
            assert isinstance(test, dict)
            outcome = test["status"]
            assert isinstance(outcome, str)
            parsed[outcome] += 1
    for field in PLAYWRIGHT_STAT_COUNTERS:
        if counters[field] != parsed[field]:
            raise ValueError(
                # Explanation before the numbers, deliberately: the shared
                # redactor treats `passes=2` as a credential assignment and
                # its value extent runs to the end of the line, so a reason
                # written after a `key=value` would be redacted away with
                # the counter and the operator would be told only that
                # something was wrong.
                f"report stats.{field} contradicts parsed counters "
                f"(reported {counters[field]}, parsed {parsed[field]})"
            )


def validate_report_json(data: bytes | str) -> list[dict[str, object]]:
    """Parse a Playwright JSON report and return its validated reader records."""
    try:
        report = strict_json_loads(data)
    except ValueError as exc:
        raise ValueError(f"invalid report JSON: {exc}") from exc
    validate_json_shape(report)
    records = report_records(report)
    encode_json(records)
    return records


def report_records(report: object) -> list[dict[str, object]]:
    records = synthetic_error_records(report)
    specs = report_specs(report)
    validate_report_stats(report, specs)
    for spec in specs:
        tests = spec.get("tests")
        assert isinstance(tests, list)
        for test in tests:
            if not isinstance(test, dict):
                continue
            outcome = test.get("status")
            if outcome in {"expected", "skipped"}:
                continue
            raw_attempts = test.get("results")
            attempts: list[dict[str, object]] = []
            if isinstance(raw_attempts, list):
                for index, result in enumerate(raw_attempts):
                    if index >= MAX_ATTEMPTS_PER_TEST:
                        raise ValueError(
                            f"test exceeds the "
                            f"{MAX_ATTEMPTS_PER_TEST}-attempt limit"
                        )
                    if not isinstance(result, dict):
                        continue
                    retry = result.get("retry")
                    error = result.get("error")
                    nested_error_location = (
                        error.get("location")
                        if isinstance(error, dict)
                        else None
                    )
                    attempts.append(
                        {
                            "attempt": retry if isinstance(retry, int) else index,
                            "status": bounded_string(result.get("status")),
                            "duration": bounded_scalar(result.get("duration")),
                            "error": error_message(error),
                            "errorLocation": bounded_location(
                                nested_error_location
                                if isinstance(nested_error_location, dict)
                                else result.get("errorLocation")
                            ),
                        }
                    )
            records.append(
                {
                    "title": bounded_string(spec.get("title")),
                    "file": bounded_string(spec.get("file")),
                    "line": bounded_scalar(spec.get("line")),
                    "projectName": bounded_string(test.get("projectName")),
                    "outcome": bounded_string(outcome),
                    "retries": max(len(attempts) - 1, 0),
                    "attempts": attempts,
                }
            )
            if len(records) > MAX_OUTPUT_RECORDS:
                raise ValueError(
                    f"report exceeds the {MAX_OUTPUT_RECORDS}-record limit"
                )
    return records


def safe_zip_infos(archive: zipfile.ZipFile) -> dict[str, zipfile.ZipInfo]:
    infos = archive.infolist()
    if len(infos) > MAX_ZIP_ENTRIES:
        raise ValueError(f"ZIP exceeds the {MAX_ZIP_ENTRIES}-entry limit")
    by_name: dict[str, zipfile.ZipInfo] = {}
    total_size = 0
    for index, info in enumerate(infos):
        if info.filename in by_name:
            raise ValueError(f"duplicate ZIP entry at entry index {index}")
        by_name[info.filename] = info
        path = PurePosixPath(info.filename)
        if (
            not info.filename
            or info.filename.startswith("/")
            or "\\" in info.filename
            or ".." in path.parts
        ):
            raise ValueError(f"unsafe ZIP entry name at entry index {index}")
        mode = info.external_attr >> 16
        file_type = stat.S_IFMT(mode)
        name_is_directory = info.filename.endswith("/")
        mode_is_directory = bool(file_type) and stat.S_ISDIR(mode)
        if file_type and name_is_directory != mode_is_directory:
            raise ValueError(
                "ZIP directory mode/name disagreement at entry index "
                f"{index}"
            )
        if stat.S_ISLNK(mode):
            raise ValueError(
                f"symlink ZIP entry is forbidden at entry index {index}"
            )
        if file_type and not (
            stat.S_ISREG(mode) or stat.S_ISDIR(mode)
        ):
            raise ValueError(
                "special-file ZIP entry is forbidden "
                f"at entry index {index}"
            )
        if info.flag_bits & 0x1:
            raise ValueError(
                f"encrypted ZIP entry is forbidden at entry index {index}"
            )
        if info.compress_type not in ALLOWED_ZIP_METHODS:
            raise ValueError(
                f"unsupported ZIP compression method at entry index {index}"
            )
        if info.file_size > MAX_ZIP_ENTRY_BYTES:
            raise ValueError(
                f"ZIP entry exceeds the {MAX_ZIP_ENTRY_BYTES}-byte limit "
                f"at entry index {index}"
            )
        total_size += info.file_size
        if total_size > MAX_ZIP_TOTAL_BYTES:
            raise ValueError(
                f"ZIP exceeds the {MAX_ZIP_TOTAL_BYTES}-byte expanded limit"
            )
        if info.file_size:
            if not info.compress_size:
                raise ValueError(
                    "ZIP entry has an invalid compression ratio "
                    f"at entry index {index}"
                )
            ratio = info.file_size / info.compress_size
            if ratio > MAX_COMPRESSION_RATIO:
                raise ValueError(
                    f"ZIP entry exceeds the {MAX_COMPRESSION_RATIO}:1 "
                    f"compression ratio at entry index {index}"
                )
    return by_name


def open_trace_archive(
    data: bytes,
) -> tuple[zipfile.ZipFile, dict[str, zipfile.ZipInfo]]:
    archive: zipfile.ZipFile | None = None
    try:
        archive = zipfile.ZipFile(BytesIO(data))
        return archive, safe_zip_infos(archive)
    except ValueError:
        if archive is not None:
            archive.close()
        raise
    except (zipfile.BadZipFile, RuntimeError) as exc:
        if archive is not None:
            archive.close()
        raise ValueError(f"invalid or unsupported ZIP: {exc}") from exc


def validate_trace_archive_payloads(data: bytes) -> None:
    """Read every member fully so CRC and decompression failures fail closed."""
    archive, infos = open_trace_archive(data)
    try:
        with archive:
            for index, info in enumerate(infos.values()):
                if info.is_dir():
                    continue
                expanded = 0
                with archive.open(info, "r") as source:
                    while True:
                        chunk = source.read(64 * 1024)
                        if not chunk:
                            break
                        expanded += len(chunk)
                        if expanded > info.file_size:
                            raise ValueError(
                                "ZIP entry expanded beyond its declared size "
                                f"at entry index {index}"
                            )
                if expanded != info.file_size:
                    raise ValueError(
                        "ZIP entry size contradicts its payload "
                        f"at entry index {index}"
                    )
    except (zipfile.BadZipFile, RuntimeError, EOFError, zlib.error) as exc:
        raise ValueError(f"invalid or corrupt ZIP entry payload: {exc}") from exc


def projected_error(value: object) -> dict[str, object] | None:
    if isinstance(value, str):
        return {"message": trace_string(value)}
    if not isinstance(value, dict):
        return None
    return {
        "name": trace_string(value.get("name")),
        "message": trace_string(value.get("message")),
        "stack": trace_string(value.get("stack")),
    }


def trace_string(value: object) -> str | None:
    return (
        redact_string(value)[:MAX_STRING_CHARS]
        if isinstance(value, str)
        else None
    )


def projected_trace_location(value: object) -> dict[str, object] | None:
    if not isinstance(value, dict):
        return None
    return {
        "file": trace_string(value.get("file")),
        "line": (
            value.get("line")
            if isinstance(value.get("line"), int)
            and not isinstance(value.get("line"), bool)
            else None
        ),
        "column": (
            value.get("column")
            if isinstance(value.get("column"), int)
            and not isinstance(value.get("column"), bool)
            else None
        ),
    }


def project_trace_record(record: object, entry: str) -> dict[str, object] | None:
    if not isinstance(record, dict):
        return None
    if entry.endswith("trace.network"):
        if record.get("type") != "resource-snapshot":
            return None
        snapshot = record.get("snapshot")
        if not isinstance(snapshot, dict):
            return None
        request = snapshot.get("request")
        response = snapshot.get("response")
        request = request if isinstance(request, dict) else {}
        response = response if isinstance(response, dict) else {}
        status = response.get("status")
        failure = (
            snapshot.get("_failureText")
            or response.get("errorText")
            or request.get("failure")
        )
        if isinstance(failure, dict):
            failure = failure.get("errorText") or failure.get("message")
        failure_text = trace_string(failure)
        if not (
            isinstance(status, (int, float))
            and not isinstance(status, bool)
            and status >= 400
        ) and not failure_text:
            return None
        return redact_sensitive(
            {
                "kind": "network-error",
                "method": trace_string(request.get("method")),
                "url": trace_string(request.get("url") or snapshot.get("url")),
                "status": (
                    status
                    if isinstance(status, (int, float))
                    and not isinstance(status, bool)
                    else None
                ),
                "statusText": trace_string(response.get("statusText")),
                "failure": failure_text,
            }
        )

    record_type = record.get("type")
    if record_type == "after" and record.get("error") is not None:
        return redact_sensitive(
            {
                "kind": "failed-action",
                "apiName": trace_string(record.get("apiName")),
                "callId": trace_string(record.get("callId")),
                "error": projected_error(record.get("error")),
            }
        )
    if (
        record_type == "console"
        and str(record.get("messageType", "")).lower() == "error"
    ):
        return redact_sensitive(
            {
                "kind": "console-error",
                "text": trace_string(record.get("text")),
                "location": projected_trace_location(record.get("location")),
            }
        )
    method = str(record.get("method", "")).lower().replace("-", "")
    normalized_type = str(record_type or "").lower().replace("-", "")
    if method == "pageerror" or normalized_type == "pageerror":
        params = record.get("params")
        params = params if isinstance(params, dict) else {}
        error = (
            params.get("error")
            or record.get("error")
            or params.get("message")
            or record.get("message")
        )
        return redact_sensitive(
            {
                "kind": "page-error",
                "error": projected_error(error),
            }
        )
    return None


def read_trace_entry(data: bytes, entry: str) -> list[object]:
    if not EXPECTED_TRACE_ENTRY.fullmatch(entry):
        raise ValueError(
            "entry is not an expected trace entry "
            "(trace.trace, trace.network, or a numeric-prefixed equivalent)"
        )
    archive, infos = open_trace_archive(data)
    try:
        with archive:
            info = infos.get(entry)
            if info is None:
                raise ValueError(f"expected trace entry is absent: {entry}")
            mode = info.external_attr >> 16
            file_type = stat.S_IFMT(mode)
            if (
                info.is_dir()
                or stat.S_ISDIR(mode)
                or (file_type and not stat.S_ISREG(mode))
            ):
                raise ValueError(
                    f"selected trace entry is not a regular file: {entry}"
                )
            if info.file_size > MAX_SELECTED_ENTRY_BYTES:
                raise ValueError(
                    f"selected entry exceeds the "
                    f"{MAX_SELECTED_ENTRY_BYTES}-byte limit: {entry}"
                )
            records: list[object] = []
            projected_bytes = 2
            selected_bytes = 0
            with archive.open(info, "r") as source:
                line_number = 0
                while True:
                    line = source.readline(MAX_NDJSON_LINE_BYTES + 2)
                    if not line:
                        break
                    line_number += 1
                    selected_bytes += len(line)
                    if selected_bytes > MAX_SELECTED_ENTRY_BYTES:
                        raise ValueError(
                            f"selected entry exceeds the "
                            f"{MAX_SELECTED_ENTRY_BYTES}-byte limit: {entry}"
                        )
                    if len(line.rstrip(b"\r\n")) > MAX_NDJSON_LINE_BYTES:
                        raise ValueError(
                            f"trace line {line_number} exceeds the "
                            f"{MAX_NDJSON_LINE_BYTES}-byte limit"
                        )
                    if not line.strip():
                        continue
                    try:
                        record = strict_json_loads(line)
                    except ValueError as exc:
                        raise ValueError(
                            f"invalid trace JSON on line {line_number}: {exc}"
                        ) from exc
                    validate_json_shape(record)
                    projected = project_trace_record(record, entry)
                    if projected is None:
                        continue
                    encoded = json.dumps(
                        projected,
                        ensure_ascii=False,
                        sort_keys=True,
                        separators=(",", ":"),
                        allow_nan=False,
                    ).encode("utf-8")
                    projected_bytes += len(encoded) + (1 if records else 0)
                    if projected_bytes > MAX_OUTPUT_BYTES:
                        raise ValueError(
                            f"trace projection exceeds the "
                            f"{MAX_OUTPUT_BYTES}-byte output limit"
                        )
                    records.append(projected)
                    if len(records) > MAX_OUTPUT_RECORDS:
                        raise ValueError(
                            f"trace exceeds the "
                            f"{MAX_OUTPUT_RECORDS}-diagnostic output limit"
                        )
            return records
    except (zipfile.BadZipFile, RuntimeError) as exc:
        raise ValueError(f"invalid or corrupt ZIP entry: {exc}") from exc


def encode_json(value: object) -> bytes:
    value = redact_sensitive(value)
    if redact_sensitive(value) != value:
        raise ValueError("credential redaction left residual sensitive output")
    validate_json_shape(value)
    payload = json.dumps(
        value,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    ).encode("utf-8")
    if has_residual_credential(payload.decode("utf-8")):
        raise ValueError("credential redaction left residual sensitive output")
    if len(payload) > MAX_OUTPUT_BYTES:
        raise ValueError(f"output exceeds the {MAX_OUTPUT_BYTES}-byte limit")
    return payload


def emit_json(value: object) -> None:
    print(encode_json(value).decode("utf-8"))


def main() -> None:
    parser = argparse.ArgumentParser()
    subparsers = parser.add_subparsers(dest="mode", required=True)
    for mode in ("report", "trace", "media", "trace-snapshot"):
        command = subparsers.add_parser(mode)
        command.add_argument(
            "--report-root",
            required=True,
            type=Path,
            help="trusted non-symlink directory containing the artifact",
        )
        command.add_argument("artifact", type=Path)
        if mode == "trace":
            selection = command.add_mutually_exclusive_group(required=True)
            selection.add_argument("--entry")
            selection.add_argument(
                "--list",
                action="store_true",
                help="list only expected trace JSON entries",
            )
    args = parser.parse_args()

    try:
        if args.mode == "report":
            data = read_bounded_file(
                args.report_root,
                args.artifact,
                MAX_REPORT_BYTES,
            )
            emit_json(validate_report_json(data))
        elif args.mode == "trace":
            data = read_bounded_file(
                args.report_root,
                args.artifact,
                MAX_ARCHIVE_BYTES,
            )
            if args.list:
                archive, infos = open_trace_archive(data)
                with archive:
                    emit_json(
                        sorted(
                            name
                            for name, info in infos.items()
                            if not info.is_dir()
                            and EXPECTED_TRACE_ENTRY.fullmatch(name)
                        )
                    )
            else:
                emit_json(read_trace_entry(data, args.entry))
        elif args.mode == "media":
            emit_json(media_metadata(args.report_root, args.artifact))
        else:
            if args.artifact.suffix.lower() != ".zip":
                raise ValueError("trace-snapshot mode accepts only .zip files")
            data = read_bounded_file(
                args.report_root,
                args.artifact,
                MAX_ARCHIVE_BYTES,
            )
            validate_trace_archive_payloads(data)
            emit_json(snapshot_validated_bytes(data, kind="zip"))
    except (OSError, ValueError) as exc:
        parser.error(sanitize_diagnostic(exc, redact_string))


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
"""Read Cypress JSON and media artifacts through bounded trust gates."""

from __future__ import annotations

import argparse
from collections.abc import Iterator
from contextlib import contextmanager
import hashlib
import json
import os
from pathlib import Path
import stat
import sys
import tempfile

sys.path.insert(0, str(Path(__file__).resolve().parent))
from redact_artifact import (
    bounded_redacted,
    redact_diagnostic,
    redact_for_output,
)


MAX_JSON_BYTES = 8 * 1024 * 1024
MAX_PNG_BYTES = 64 * 1024 * 1024
MAX_MP4_BYTES = 512 * 1024 * 1024
MAX_JSON_DEPTH = 100
MAX_JSON_NODES = 200_000
MAX_OUTPUT_BYTES = 1024 * 1024
MAX_OUTPUT_RECORDS = 10_000
MAX_ATTEMPTS_PER_TEST = 100
MAX_STRING_CHARS = 4_000
REQUIRED_MOCHAWESOME_STATS = (
    "suites",
    "tests",
    "passes",
    "pending",
    "failures",
    "skipped",
    "duration",
)
OPTIONAL_MOCHAWESOME_INTEGER_STATS = ("testsRegistered", "other")
OPTIONAL_MOCHAWESOME_BOOLEAN_STATS = ("hasOther", "hasSkipped")
OPTIONAL_MOCHAWESOME_PERCENT_STATS = ("passPercent", "pendingPercent")
CYPRESS_RUN_RESULT_STATES = {"passed", "failed", "pending", "skipped"}


def require_secure_descriptor_support() -> tuple[int, int]:
    directory_flag = getattr(os, "O_DIRECTORY", None)
    no_follow_flag = getattr(os, "O_NOFOLLOW", None)
    if (
        os.name != "posix"
        or not isinstance(directory_flag, int)
        or not isinstance(no_follow_flag, int)
        or os.open not in getattr(os, "supports_dir_fd", set())
    ):
        raise ValueError(
            "secure artifact reading requires POSIX descriptor-relative "
            "no-follow support (macOS, Linux, or Windows via WSL); "
            "native Windows is unsupported"
        )
    close_on_exec = getattr(os, "O_CLOEXEC", 0)
    return (
        os.O_RDONLY | directory_flag | no_follow_flag | close_on_exec,
        os.O_RDONLY
        | no_follow_flag
        | getattr(os, "O_NONBLOCK", 0)
        | close_on_exec,
    )


def reject_duplicate_keys(pairs: list[tuple[str, object]]) -> dict[str, object]:
    value: dict[str, object] = {}
    for position, (key, item) in enumerate(pairs):
        if key in value:
            # The key itself is artifact-controlled and this error travels to
            # stderr through `parser.error`, which never reaches the emission
            # gate. Report the position instead of echoing the bytes.
            raise ValueError(f"duplicate JSON key at object entry {position}")
        value[key] = item
    return value


def reject_nonfinite_number(token: str) -> object:
    raise ValueError(f"non-finite JSON number is forbidden: {token}")


def strict_json_loads(data: bytes | str) -> object:
    if isinstance(data, bytes):
        if data.startswith(b"\xef\xbb\xbf"):
            raise ValueError("JSON BOM is forbidden")
        try:
            text = data.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise ValueError(f"invalid JSON UTF-8: {exc}") from exc
    else:
        text = data
    if text.startswith("\ufeff"):
        raise ValueError("JSON BOM is forbidden")
    start = len(text) - len(text.lstrip())
    if start == len(text):
        raise ValueError("invalid JSON: input is empty")
    decoder = json.JSONDecoder(
        object_pairs_hook=reject_duplicate_keys,
        parse_constant=reject_nonfinite_number,
    )
    try:
        value, end = decoder.raw_decode(text, start)
    except (RecursionError, json.JSONDecodeError) as exc:
        raise ValueError(f"invalid JSON: {exc}") from exc
    if text[end:].strip():
        raise ValueError("invalid JSON: trailing data is forbidden")
    return value


def open_trusted_directory(path: Path, description: str) -> int:
    """Open an absolute directory from the filesystem root without following links."""
    directory_flags, _ = require_secure_descriptor_support()
    absolute = Path(os.path.abspath(path))
    current_fd: int | None = None
    try:
        current_fd = os.open(absolute.anchor, directory_flags)
        for component in absolute.parts[1:]:
            next_fd = os.open(component, directory_flags, dir_fd=current_fd)
            os.close(current_fd)
            current_fd = next_fd
        return current_fd
    except OSError as exc:
        if current_fd is not None:
            os.close(current_fd)
        raise ValueError(
            f"{description} contains a symlink or is unavailable: {path}: {exc}"
        ) from exc


def descriptor_fingerprint(metadata: os.stat_result) -> tuple[int, ...]:
    fingerprint = (
        metadata.st_dev,
        metadata.st_ino,
        metadata.st_mode,
        metadata.st_size,
        metadata.st_mtime_ns,
    )
    ctime_ns = getattr(metadata, "st_ctime_ns", None)
    if ctime_ns is not None:
        return fingerprint + (ctime_ns,)
    return fingerprint


def require_unchanged_descriptor(
    artifact_fd: int,
    original_metadata: os.stat_result,
    artifact: Path,
) -> os.stat_result:
    current_metadata = os.fstat(artifact_fd)
    if descriptor_fingerprint(current_metadata) != descriptor_fingerprint(
        original_metadata
    ):
        raise ValueError(f"artifact changed while being read: {artifact}")
    return current_metadata


@contextmanager
def open_artifact_descriptor(
    artifact_root: Path,
    artifact: Path,
    max_bytes: int,
) -> Iterator[tuple[int, os.stat_result]]:
    directory_flags, file_flags = require_secure_descriptor_support()
    absolute_root = Path(os.path.abspath(artifact_root))
    absolute_artifact = Path(os.path.abspath(artifact))
    try:
        lexical_relative = absolute_artifact.relative_to(absolute_root)
    except ValueError as exc:
        raise ValueError(f"artifact is outside the artifact root: {artifact}") from exc
    if not lexical_relative.parts:
        raise ValueError(f"artifact is not a regular file: {artifact}")

    root_fd = open_trusted_directory(absolute_root, "artifact root")
    current_fd = root_fd
    opened_directory_fds: list[int] = []
    artifact_fd: int | None = None
    try:
        for component in lexical_relative.parts[:-1]:
            next_fd = os.open(component, directory_flags, dir_fd=current_fd)
            opened_directory_fds.append(next_fd)
            current_fd = next_fd
        artifact_fd = os.open(
            lexical_relative.parts[-1],
            file_flags,
            dir_fd=current_fd,
        )
        metadata = os.fstat(artifact_fd)
        if not stat.S_ISREG(metadata.st_mode):
            raise ValueError(f"artifact is not a regular file: {artifact}")
        if metadata.st_size > max_bytes:
            raise ValueError(
                f"artifact exceeds the {max_bytes}-byte limit: {artifact}"
            )
        yield artifact_fd, metadata
    except OSError as exc:
        raise ValueError(
            f"unsafe, symlinked, or unreadable artifact path: {artifact}: {exc}"
        ) from exc
    finally:
        if artifact_fd is not None:
            os.close(artifact_fd)
        for directory_fd in reversed(opened_directory_fds):
            os.close(directory_fd)
        os.close(root_fd)


def read_artifact(
    artifact_root: Path,
    artifact: Path,
    max_bytes: int,
) -> tuple[int, bytes]:
    with open_artifact_descriptor(
        artifact_root,
        artifact,
        max_bytes,
    ) as (artifact_fd, metadata):
        chunks: list[bytes] = []
        remaining = max_bytes + 1
        while remaining:
            chunk = os.read(artifact_fd, min(64 * 1024, remaining))
            if not chunk:
                break
            chunks.append(chunk)
            remaining -= len(chunk)
        data = b"".join(chunks)
        if len(data) > max_bytes:
            raise ValueError(
                f"artifact exceeds the {max_bytes}-byte limit: {artifact}"
            )
        require_unchanged_descriptor(artifact_fd, metadata, artifact)
        if len(data) != metadata.st_size:
            raise ValueError(f"artifact changed while being read: {artifact}")
        return metadata.st_size, data


def write_all(file_descriptor: int, data: bytes) -> None:
    view = memoryview(data)
    while view:
        written = os.write(file_descriptor, view)
        if written <= 0:
            raise OSError("snapshot write made no progress")
        view = view[written:]


def remove_failed_snapshot(
    snapshot_path: Path | None,
    snapshot_directory: Path | None,
) -> None:
    if snapshot_path is not None:
        try:
            snapshot_path.unlink()
        except FileNotFoundError:
            pass
    if snapshot_directory is not None:
        try:
            snapshot_directory.rmdir()
        except FileNotFoundError:
            pass


def validate_json_shape(value: object) -> None:
    stack = [(value, 1)]
    nodes = 0
    while stack:
        current, depth = stack.pop()
        nodes += 1
        if nodes > MAX_JSON_NODES:
            raise ValueError(f"JSON exceeds the {MAX_JSON_NODES}-node limit")
        if depth > MAX_JSON_DEPTH:
            raise ValueError(f"JSON exceeds the {MAX_JSON_DEPTH}-level depth limit")
        if isinstance(current, dict):
            stack.extend((item, depth + 1) for item in current.values())
        elif isinstance(current, list):
            stack.extend((item, depth + 1) for item in current)


def load_json(data: bytes) -> object:
    try:
        value = strict_json_loads(data)
    except ValueError as exc:
        raise ValueError(f"invalid JSON: {exc}") from exc
    validate_json_shape(value)
    return value


def bounded_string(value: object) -> str | None:
    return bounded_redacted(value, MAX_STRING_CHARS)


def bounded_scalar(value: object) -> object:
    if value is None or isinstance(value, (bool, int, float)):
        return value
    if isinstance(value, str):
        return bounded_string(value)
    return None


def nonnegative_integer(value: object, field: str) -> int:
    if isinstance(value, bool) or not isinstance(value, int) or value < 0:
        raise ValueError(
            f"mochawesome stats.{field} must be a nonnegative integer"
        )
    return value


def validate_mochawesome_stats(stats: dict[str, object]) -> dict[str, int]:
    counters = {
        key: nonnegative_integer(stats.get(key), key)
        for key in REQUIRED_MOCHAWESOME_STATS
    }
    for key in OPTIONAL_MOCHAWESOME_INTEGER_STATS:
        if key in stats:
            nonnegative_integer(stats[key], key)
    for key in OPTIONAL_MOCHAWESOME_BOOLEAN_STATS:
        if key in stats and not isinstance(stats[key], bool):
            raise ValueError(f"mochawesome stats.{key} must be a boolean")
    for key in OPTIONAL_MOCHAWESOME_PERCENT_STATS:
        value = stats.get(key)
        if value is not None and (
            isinstance(value, bool)
            or not isinstance(value, (int, float))
            or value < 0
            or value > 100
        ):
            raise ValueError(
                f"mochawesome stats.{key} must be a percentage from 0 to 100"
            )
    for key in ("start", "end"):
        if key in stats and not isinstance(stats[key], str):
            raise ValueError(f"mochawesome stats.{key} must be a string")
    return counters


def error_text(value: object) -> str | None:
    if isinstance(value, dict):
        return bounded_string(value.get("message"))
    return bounded_string(value)


def screenshot_paths(context: object) -> list[str]:
    if not isinstance(context, str) or not context:
        return []
    try:
        parsed = strict_json_loads(context)
    except ValueError:
        return []
    validate_json_shape(parsed)
    paths: list[str] = []
    stack = [parsed]
    while stack:
        current = stack.pop()
        if isinstance(current, str) and current.lower().endswith(".png"):
            path = bounded_string(current)
            assert path is not None
            paths.append(path)
        elif isinstance(current, dict):
            stack.extend(current.values())
        elif isinstance(current, list):
            stack.extend(current)
        if len(paths) > MAX_OUTPUT_RECORDS:
            raise ValueError("context exceeds the screenshot-path limit")
    return paths


def mochawesome_test_classification(
    test: object,
    *,
    is_hook: bool = False,
) -> str:
    if (
        not isinstance(test, dict)
        or not isinstance(test.get("pass"), bool)
        or not isinstance(test.get("fail"), bool)
        or not isinstance(test.get("pending"), bool)
    ):
        raise ValueError(
            "mochawesome schema requires test pass/fail/pending booleans"
        )
    skipped = test.get("skipped", False)
    if not isinstance(skipped, bool):
        raise ValueError(
            "mochawesome schema requires optional test skipped boolean"
        )
    classifications = {
        "passed": test["pass"],
        "failed": test["fail"],
        "pending": test["pending"],
        "skipped": skipped,
    }
    active = [name for name, enabled in classifications.items() if enabled]
    if not active and is_hook:
        classification = "other"
    elif len(active) == 1:
        classification = active[0]
    else:
        raise ValueError(
            "mochawesome schema has contradictory test state flags"
        )
    state = test.get("state")
    if state is not None and not isinstance(state, str):
        raise ValueError(
            "mochawesome schema requires test state to be a string or null"
        )
    expected_states: dict[str, set[object]] = {
        "passed": {"passed"},
        "failed": {"failed"},
        "pending": {None, "pending"},
        "skipped": {None, "skipped"},
        "other": {None},
    }
    if state not in expected_states[classification]:
        raise ValueError(
            "mochawesome test flags contradict test state"
        )
    if is_hook and classification in {"pending", "skipped"}:
        raise ValueError("mochawesome hook cannot be pending or skipped")

    error = test.get("err")
    if not isinstance(error, dict):
        raise ValueError("mochawesome schema requires test err object")
    has_error = any(
        isinstance(error.get(field), str) and bool(error[field].strip())
        for field in ("message", "estack")
    )
    if classification == "failed" and not has_error:
        raise ValueError(
            "mochawesome failed test requires a nonempty error message or stack"
        )
    if classification != "failed" and has_error:
        raise ValueError(
            "mochawesome nonfailed test cannot contain a failure error"
        )
    return classification


def validate_mochawesome_percentage(
    stats: dict[str, object],
    field: str,
    expected: float | None,
) -> None:
    if field not in stats:
        return
    actual = stats[field]
    if expected is None:
        if actual is not None:
            raise ValueError(
                f"mochawesome stats.{field} contradicts parsed counters"
            )
        return
    if not isinstance(actual, (int, float)) or isinstance(actual, bool):
        raise ValueError(
            f"mochawesome stats.{field} must be a percentage from 0 to 100"
        )
    if abs(float(actual) - expected) > 0.011:
        raise ValueError(
            # Explanation before the numbers: see the counter check below.
            f"mochawesome stats.{field} contradicts parsed percentage "
            f"(reported {actual}, parsed {expected})"
        )


def mochawesome_output(report: object) -> dict[str, object]:
    if (
        not isinstance(report, dict)
        or not isinstance(report.get("stats"), dict)
        or not isinstance(report.get("results"), list)
    ):
        raise ValueError(
            "mochawesome schema requires root stats object and results array"
        )
    stats = report["stats"]
    counters = validate_mochawesome_stats(stats)
    records: list[dict[str, object]] = []
    parsed_counts = {
        "suites": 0,
        "tests": 0,
        "passes": 0,
        "pending": 0,
        "failures": 0,
        "skipped": 0,
        "failed_hooks": 0,
    }
    containers: list[tuple[object, str | None]] = [
        (result, None) for result in reversed(report["results"])
    ]
    while containers:
        container, inherited_file = containers.pop()
        if (
            not isinstance(container, dict)
            or not isinstance(container.get("tests"), list)
            or not isinstance(container.get("suites"), list)
        ):
            raise ValueError(
                "mochawesome schema requires tests/suites arrays on every "
                "result and suite"
            )
        file_name = bounded_string(container.get("file")) or inherited_file
        parsed_counts["suites"] += len(container["suites"])
        containers.extend(
            (suite, file_name) for suite in reversed(container["suites"])
        )
        expected_ids = {
            "passes": [],
            "failures": [],
            "pending": [],
            "skipped": [],
        }
        for test in container["tests"]:
            if not isinstance(test, dict):
                raise ValueError(
                    "mochawesome schema requires test objects"
                )
            if test.get("isHook", False) is not False:
                raise ValueError(
                    "mochawesome suite tests cannot be hook records"
                )
            classification = mochawesome_test_classification(test)
            test_uuid = test.get("uuid")
            if not isinstance(test_uuid, str) or not test_uuid:
                raise ValueError(
                    "mochawesome schema requires nonempty test uuid strings"
                )
            list_name = {
                "passed": "passes",
                "failed": "failures",
                "pending": "pending",
                "skipped": "skipped",
            }[classification]
            expected_ids[list_name].append(test_uuid)
            parsed_counts["tests"] += 1
            if classification == "passed":
                parsed_counts["passes"] += 1
            elif classification == "failed":
                parsed_counts["failures"] += 1
            elif classification == "pending":
                parsed_counts["pending"] += 1
            else:
                parsed_counts["skipped"] += 1
            if classification != "failed":
                continue
            error = test["err"]
            assert isinstance(error, dict)
            records.append(
                {
                    "file": file_name,
                    "title": bounded_string(test.get("title")),
                    "fullTitle": bounded_string(test.get("fullTitle")),
                    "duration": bounded_scalar(test.get("duration")),
                    "state": bounded_string(test.get("state")),
                    "error": bounded_string(error.get("message")),
                    "stack": bounded_string(error.get("estack")),
                    "screenshots": screenshot_paths(test.get("context")),
                }
            )
            if len(records) > MAX_OUTPUT_RECORDS:
                raise ValueError(
                    f"mochawesome report exceeds the "
                    f"{MAX_OUTPUT_RECORDS}-record limit"
                )
        for list_name, expected in expected_ids.items():
            actual = container.get(list_name)
            if (
                not isinstance(actual, list)
                or not all(isinstance(item, str) for item in actual)
                or actual != expected
            ):
                raise ValueError(
                    f"mochawesome suite {list_name} contradicts test flags"
                )
        for hook_field in ("beforeHooks", "afterHooks"):
            hooks = container.get(hook_field, [])
            if not isinstance(hooks, list):
                raise ValueError(
                    f"mochawesome schema requires optional {hook_field} array"
                )
            for hook in hooks:
                if (
                    not isinstance(hook, dict)
                    or hook.get("isHook") is not True
                ):
                    raise ValueError(
                        f"mochawesome {hook_field} entries must be hook records"
                    )
                classification = mochawesome_test_classification(
                    hook, is_hook=True
                )
                if classification == "failed":
                    parsed_counts["failed_hooks"] += 1
                    error = hook["err"]
                    assert isinstance(error, dict)
                    records.append(
                        {
                            "file": file_name,
                            "title": bounded_string(hook.get("title")),
                            "fullTitle": bounded_string(
                                hook.get("fullTitle")
                            ),
                            "duration": bounded_scalar(
                                hook.get("duration")
                            ),
                            "state": bounded_string(hook.get("state")),
                            "error": bounded_string(error.get("message")),
                            "stack": bounded_string(error.get("estack")),
                            "screenshots": screenshot_paths(
                                hook.get("context")
                            ),
                            "hook": hook_field,
                        }
                    )
                    if len(records) > MAX_OUTPUT_RECORDS:
                        raise ValueError(
                            f"mochawesome report exceeds the "
                            f"{MAX_OUTPUT_RECORDS}-record limit"
                        )

    runnable_tests = parsed_counts["tests"] - parsed_counts["skipped"]
    expected_stats = {
        "suites": parsed_counts["suites"],
        "tests": runnable_tests,
        "passes": parsed_counts["passes"],
        "pending": parsed_counts["pending"],
        "failures": parsed_counts["failures"],
        "skipped": parsed_counts["skipped"],
    }
    for key, expected_value in expected_stats.items():
        if counters[key] != expected_value:
            raise ValueError(
                # Explanation before the numbers, deliberately: the shared
                # redactor treats `passes=2` as a credential assignment and
                # its value extent runs to the end of the line, so a reason
                # written after a `key=value` would be redacted away with
                # the counter and the operator would be told only that
                # something was wrong.
                f"mochawesome stats.{key} contradicts parsed counters "
                f"(reported {counters[key]}, parsed {expected_value})"
            )
    for key in ("testsRegistered",):
        if key in stats and stats[key] != parsed_counts["tests"]:
            raise ValueError(
                f"mochawesome stats.{key} contradicts parsed tests "
                f"(reported {stats[key]}, parsed {parsed_counts['tests']})"
            )
    if "other" in stats and stats["other"] != parsed_counts["failed_hooks"]:
        raise ValueError(
            f"mochawesome stats.other contradicts parsed failed hooks "
            f"(reported {stats['other']}, "
            f"parsed {parsed_counts['failed_hooks']})"
        )
    if "hasOther" in stats and stats["hasOther"] != (
        parsed_counts["failed_hooks"] > 0
    ):
        raise ValueError(
            "mochawesome stats.hasOther contradicts parsed failed hooks"
        )
    if "hasSkipped" in stats and stats["hasSkipped"] != (
        parsed_counts["skipped"] > 0
    ):
        raise ValueError(
            "mochawesome stats.hasSkipped contradicts parsed skipped"
        )
    registered = parsed_counts["tests"]
    pass_denominator = registered - parsed_counts["pending"]
    validate_mochawesome_percentage(
        stats,
        "passPercent",
        (
            parsed_counts["passes"] / pass_denominator * 100
            if pass_denominator
            else None
        ),
    )
    validate_mochawesome_percentage(
        stats,
        "pendingPercent",
        (
            parsed_counts["pending"] / registered * 100
            if registered
            else None
        ),
    )

    return {
        "stats": {
            key: counters[key] for key in REQUIRED_MOCHAWESOME_STATS
        },
        "failures": records,
    }


def run_result_records(report: object) -> list[dict[str, object]]:
    if not isinstance(report, dict) or not isinstance(report.get("runs"), list):
        raise ValueError("run-results schema requires a root runs array")
    records: list[dict[str, object]] = []
    for run in report["runs"]:
        if not isinstance(run, dict):
            raise ValueError("run-results schema requires run objects")
        spec = run.get("spec")
        tests = run.get("tests")
        if not isinstance(spec, dict) or not isinstance(
            spec.get("relative"), str
        ) or not isinstance(tests, list):
            raise ValueError(
                "run-results schema requires spec.relative and tests array"
            )
        for test in tests:
            if (
                not isinstance(test, dict)
                or not isinstance(test.get("title"), list)
                or not all(isinstance(part, str) for part in test["title"])
                or not isinstance(test.get("state"), str)
                or not isinstance(test.get("attempts"), list)
            ):
                raise ValueError(
                    "run-results schema requires title/state/attempts"
                )
            test_state = test["state"]
            raw_attempts = test["attempts"]
            assert isinstance(test_state, str)
            assert isinstance(raw_attempts, list)
            if test_state not in CYPRESS_RUN_RESULT_STATES:
                raise ValueError(
                    f"run-results test state is unsupported: {test_state}"
                )
            if not raw_attempts:
                raise ValueError(
                    "run-results tests require at least one attempt"
                )
            attempts: list[dict[str, object]] = []
            attempt_states: list[str] = []
            for index, attempt in enumerate(raw_attempts):
                if index >= MAX_ATTEMPTS_PER_TEST:
                    raise ValueError(
                        f"test exceeds the {MAX_ATTEMPTS_PER_TEST}-attempt limit"
                    )
                if not isinstance(attempt, dict) or not isinstance(
                    attempt.get("state"), str
                ):
                    raise ValueError(
                        "run-results schema requires attempt state strings"
                    )
                attempt_state = attempt["state"]
                assert isinstance(attempt_state, str)
                if attempt_state not in CYPRESS_RUN_RESULT_STATES:
                    raise ValueError(
                        "run-results attempt state is unsupported: "
                        f"{attempt_state}"
                    )
                attempt_states.append(attempt_state)
                attempts.append(
                    {
                        "attempt": index,
                        "state": bounded_string(attempt_state),
                        "error": error_text(
                            attempt.get("error")
                            or attempt.get("displayError")
                        ),
                    }
                )
            if attempt_states[-1] != test_state:
                raise ValueError(
                    f"run-results final test state={test_state} contradicts "
                    f"last attempt state={attempt_states[-1]}"
                )
            records.append(
                {
                    "file": bounded_string(spec["relative"]),
                    "title": bounded_string(" ".join(test["title"])),
                    "state": bounded_string(test_state),
                    "duration": bounded_scalar(test.get("duration")),
                    "attempts": attempts,
                }
            )
            if len(records) > MAX_OUTPUT_RECORDS:
                raise ValueError(
                    f"run-results exceeds the {MAX_OUTPUT_RECORDS}-record limit"
                )
    return records


def media_metadata(
    artifact_root: Path,
    artifact: Path,
) -> dict[str, object]:
    suffix = artifact.suffix.lower()
    if suffix == ".png":
        kind = "png"
        max_bytes = MAX_PNG_BYTES
        expected_magic = b"\x89PNG\r\n\x1a\n"
    elif suffix == ".mp4":
        kind = "mp4"
        max_bytes = MAX_MP4_BYTES
        expected_magic = None
    else:
        raise ValueError("media mode accepts only .png and .mp4 files")

    snapshot_directory: Path | None = None
    snapshot_path: Path | None = None
    try:
        with open_artifact_descriptor(
            artifact_root,
            artifact,
            max_bytes,
        ) as (artifact_fd, metadata):
            header = os.read(artifact_fd, 16)
            if expected_magic is not None and not header.startswith(
                expected_magic
            ):
                raise ValueError("PNG artifact has an invalid signature")
            if kind == "mp4" and (
                len(header) < 12 or header[4:8] != b"ftyp"
            ):
                raise ValueError("MP4 artifact has an invalid ftyp signature")
            os.lseek(artifact_fd, 0, os.SEEK_SET)

            snapshot_directory = Path(
                tempfile.mkdtemp(prefix="e2e-cypress-media-")
            )
            os.chmod(snapshot_directory, stat.S_IRWXU)
            snapshot_path = snapshot_directory / f"artifact.{kind}"
            snapshot_flags = (
                os.O_WRONLY
                | os.O_CREAT
                | os.O_EXCL
                | getattr(os, "O_CLOEXEC", 0)
                | getattr(os, "O_NOFOLLOW", 0)
            )
            snapshot_fd = os.open(
                snapshot_path,
                snapshot_flags,
                stat.S_IRUSR,
            )
            digest = hashlib.sha256()
            copied = 0
            try:
                while True:
                    chunk = os.read(artifact_fd, 64 * 1024)
                    if not chunk:
                        break
                    copied += len(chunk)
                    if copied > max_bytes:
                        raise ValueError(
                            f"artifact exceeds the {max_bytes}-byte limit: "
                            f"{artifact}"
                        )
                    digest.update(chunk)
                    write_all(snapshot_fd, chunk)
                require_unchanged_descriptor(
                    artifact_fd,
                    metadata,
                    artifact,
                )
                if copied != metadata.st_size:
                    raise ValueError(
                        f"artifact changed while being read: {artifact}"
                    )
                os.fsync(snapshot_fd)
                os.fchmod(snapshot_fd, stat.S_IRUSR)
                snapshot_metadata = os.fstat(snapshot_fd)
                if (
                    not stat.S_ISREG(snapshot_metadata.st_mode)
                    or snapshot_metadata.st_size != copied
                    or stat.S_IMODE(snapshot_metadata.st_mode)
                    != stat.S_IRUSR
                ):
                    raise ValueError("media snapshot validation failed")
            finally:
                os.close(snapshot_fd)

        return {
            "path": str(snapshot_path),
            "snapshot_directory": str(snapshot_directory),
            "kind": kind,
            "size": copied,
            "sha256": digest.hexdigest(),
            "lifecycle": (
                "temporary owner-only snapshot; delete snapshot_directory "
                "after the viewer closes"
            ),
        }
    except BaseException:
        remove_failed_snapshot(snapshot_path, snapshot_directory)
        raise


def emit_json(value: object) -> None:
    value = redact_for_output(value)
    validate_json_shape(value)
    payload = json.dumps(
        value,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    ).encode("utf-8")
    if len(payload) > MAX_OUTPUT_BYTES:
        raise ValueError(f"output exceeds the {MAX_OUTPUT_BYTES}-byte limit")
    print(payload.decode("utf-8"))


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument(
        "mode",
        choices=("mochawesome", "run-results", "media"),
    )
    parser.add_argument(
        "--artifact-root",
        required=True,
        type=Path,
        help="trusted non-symlink directory containing the artifact",
    )
    parser.add_argument("artifact", type=Path)
    args = parser.parse_args()

    try:
        require_secure_descriptor_support()
        if args.mode == "media":
            emit_json(media_metadata(args.artifact_root, args.artifact))
        else:
            _, data = read_artifact(
                args.artifact_root,
                args.artifact,
                MAX_JSON_BYTES,
            )
            report = load_json(data)
            records = (
                mochawesome_output(report)
                if args.mode == "mochawesome"
                else run_result_records(report)
            )
            emit_json(records)
    except (OSError, ValueError) as exc:
        parser.error(redact_diagnostic(exc))


if __name__ == "__main__":
    main()
